class Solution
{
    int best = 0;
    void dfs(TreeNode* node, TreeNode* parent, int length)
    {
        if (!node)
        {
            return;
        }
        int current = parent && node->val == parent->val + 1 ? length + 1 : 1;
        best = max(best, current);
        dfs(node->left, node, current);
        dfs(node->right, node, current);
    }
public:
    int longestConsecutive(TreeNode* root)
    {
        best = 0;
        dfs(root, nullptr, 0);
        return best;
    }
};
